import { describe, expect, test } from 'vitest';
import {
  computeActivationCoverage,
  computePhotoCoverage,
  coverageMultiplier,
  pickNextBestCapture,
  runLeaveCheck,
} from '@/lib/coverage';
import type { BBOActivation } from '@/types';
import fixture from './fixtures/food-activation.json';

/**
 * A real plan generated by the live pipeline for a food activation with kitchen
 * access approved — 3 Reels, 40 shots, 14 photos. Everything here exercises the
 * deterministic shoot-day logic against output an actual model produced, not a
 * hand-written best case.
 */
const base = fixture as unknown as BBOActivation;

function withCompleted(predicate: (id: string) => boolean): BBOActivation {
  return {
    ...base,
    shots: base.shots.map((shot) => ({ ...shot, completed: predicate(shot.id) })),
    photoPlan: base.photoPlan.map((photo) => ({ ...photo, completed: predicate(photo.id) })),
  };
}

const everything = () => true;

describe('generated food plan', () => {
  test('covers the process work kitchen access unlocked', () => {
    const titles = base.shots.map((shot) => shot.title.toLowerCase()).join(' | ');
    expect(base.shots.some((shot) => shot.category === 'service')).toBe(true);
    expect(titles).toContain('chef hands');
    expect(titles).toContain('plating');
  });

  test('photo plan covers hero food, spread, group hero and the venue', () => {
    const categories = new Set(base.photoPlan.map((photo) => photo.category));
    expect(categories.has('hero-food')).toBe(true);
    expect(categories.has('full-spread')).toBe(true);
    expect(categories.has('group-hero')).toBe(true);
    expect(categories.has('venue')).toBe(true);
  });

  test('every client priority produced at least one client-required capture', () => {
    const clientCaptures = [
      ...base.shots.filter((shot) => shot.clientRequired),
      ...base.photoPlan.filter((photo) => photo.clientRequired),
    ];
    expect(clientCaptures.length).toBeGreaterThanOrEqual(base.clientRequirements.length);
  });

  test('the hero dish is planned as an untouched frame', () => {
    const perishable = computePhotoCoverage(base.photoPlan).perishableRemaining;
    expect(perishable.some((photo) => photo.category === 'hero-food')).toBe(true);
  });

  test('at least one camera setup serves more than one Reel', () => {
    const selected = new Set(base.reels.filter((reel) => reel.selected).map((reel) => reel.id));
    const shared = base.shots.filter((shot) => coverageMultiplier(shot, selected) > 1);
    expect(shared.length).toBeGreaterThan(0);
  });
});

describe('CAN WE LEAVE? on the real plan', () => {
  test('a fresh plan is nowhere near ready', () => {
    const result = runLeaveCheck(base);
    expect(result.clear).toBe(false);
    expect(result.blockers.length).toBeGreaterThan(5);
  });

  test('names the missing group hero photo specifically', () => {
    const almost = withCompleted((id) => id !== 'photo-shot-3');
    const groupHero = base.photoPlan.find((photo) => photo.category === 'group-hero');
    const activation: BBOActivation = {
      ...almost,
      photoPlan: almost.photoPlan.map((photo) =>
        photo.category === 'group-hero' ? { ...photo, completed: false } : photo
      ),
      verdict: { value: 'stamped' },
    };

    const result = runLeaveCheck(activation);
    expect(result.clear).toBe(false);
    expect(result.blockers.some((blocker) => blocker.title === groupHero?.title)).toBe(true);
  });

  test('a single outstanding client-required capture still blocks the exit', () => {
    const clientShot = base.shots.find((shot) => shot.clientRequired)!;
    const activation: BBOActivation = {
      ...withCompleted(everything),
      shots: base.shots.map((shot) => ({
        ...shot,
        completed: shot.id !== clientShot.id,
      })),
      verdict: { value: 'stamped' },
    };

    const result = runLeaveCheck(activation);
    expect(result.clear).toBe(false);
    expect(result.blockers.some((blocker) => blocker.title === clientShot.title)).toBe(true);
  });

  test('an outstanding kitchen process MUST blocks the exit', () => {
    const process = base.shots.find(
      (shot) => shot.category === 'service' && shot.priority === 'must'
    )!;
    const activation: BBOActivation = {
      ...withCompleted(everything),
      shots: base.shots.map((shot) => ({ ...shot, completed: shot.id !== process.id })),
      verdict: { value: 'stamped' },
    };

    expect(runLeaveCheck(activation).blockers.some((b) => b.title === process.title)).toBe(true);
  });

  test('the missing verdict is the last thing standing', () => {
    const result = runLeaveCheck(withCompleted(everything));
    expect(result.clear).toBe(false);
    expect(result.blockers.map((blocker) => blocker.kind)).toEqual(['verdict']);
  });

  test("everything required plus a verdict returns YOU'RE COVERED, with optionals still open", () => {
    const activation: BBOActivation = {
      ...base,
      // Optional captures are deliberately left unshot.
      shots: base.shots.map((shot) => ({ ...shot, completed: shot.priority !== 'optional' })),
      photoPlan: base.photoPlan.map((photo) => ({
        ...photo,
        completed: photo.priority !== 'optional',
      })),
      verdict: { value: 'stamped', notes: 'Worth the trip' },
    };

    const outstandingOptional = [
      ...activation.shots.filter((shot) => !shot.completed),
      ...activation.photoPlan.filter((photo) => !photo.completed),
    ];
    expect(outstandingOptional.length).toBeGreaterThan(0);

    const result = runLeaveCheck(activation);
    expect(result.blockers).toEqual([]);
    expect(result.clear).toBe(true);
    expect(result.readyReels.length).toBe(3);
  });
});

describe('NEXT BEST CAPTURE on the real plan', () => {
  test('once food is out, an untouched hero frame beats leftover optional B-roll', () => {
    const heroPhoto = base.photoPlan.find((photo) => photo.category === 'hero-food')!;
    const optionalShot = base.shots.find((shot) => shot.priority === 'optional');

    // Everything done except the hero food frame and the optional video.
    const activation: BBOActivation = {
      ...base,
      shots: base.shots.map((shot) => ({
        ...shot,
        completed: shot.id !== optionalShot?.id,
      })),
      photoPlan: base.photoPlan.map((photo) => ({
        ...photo,
        completed: photo.id !== heroPhoto.id,
      })),
    };

    const pick = pickNextBestCapture(activation, { serviceStarted: true });
    expect(pick?.id).toBe(heroPhoto.id);
    expect(pick?.reasons.join(' ')).toContain('before bites');
  });

  test('coverage percentages move as captures are ticked off', () => {
    const none = computeActivationCoverage(base);
    expect(none.percent).toBe(0);

    const half = withCompleted((id) => base.shots.findIndex((s) => s.id === id) % 2 === 0);
    expect(computeActivationCoverage(half).percent).toBeGreaterThan(0);

    const all = computeActivationCoverage(withCompleted(everything));
    expect(all.percent).toBe(100);
    expect(all.photos.complete).toBe(true);
    expect(all.reels.every((reel) => reel.readyToEdit)).toBe(true);
  });
});
